import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        List<Integer> ids = List.of(104, 101, 107, 101, 104, 110, 104);
        Set<Integer> vips = Set.of(101, 110, 200);

        Set<Integer> seen = new HashSet<>();
        Set<Integer> repeats = new HashSet<>();
        for (int id : ids) {
            if (!seen.add(id)) {
                repeats.add(id);
            }
        }
        System.out.println("Repeats: " + new TreeSet<>(repeats));

        Set<Integer> unique = new HashSet<>(ids);
        System.out.println("Unique ids: " + unique.size());

        int vipCount = 0;
        for (int id : unique) {
            if (vips.contains(id)) {
                vipCount++;
            }
        }
        System.out.println("VIP ids: " + vipCount);

        unique.remove(107);
        System.out.println("After removing 107: " + unique.size() + ", has 107: " + unique.contains(107));
    }
}

