        Set<String> tropical = Set.of("kiwi", "mango", "banana");

        Set<String> seen = new HashSet<>();
        Set<String> repeats = new HashSet<>();
        for (String fruit : fruits) {
            if (!seen.add(fruit)) {
                repeats.add(fruit);
            }
        }
        System.out.println("Repeats: " + new TreeSet<>(repeats));

        Set<String> unique = new HashSet<>(fruits);
        System.out.println("Unique fruits: " + unique.size());

        int tropicalCount = 0;
        for (String fruit : unique) {
            if (tropical.contains(fruit)) {
                tropicalCount++;
