import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        TreeSet<Integer> slots = new TreeSet<>();
        slots.add(690);
        slots.add(540);
        slots.add(900);
        slots.add(600);
        slots.add(780);
        System.out.println("Slots: " + slots);
        System.out.println("Earliest: " + slots.first());
        System.out.println("Latest: " + slots.last());
        System.out.println("Next at or after 620: " + slots.ceiling(620));
        System.out.println("Last before 620: " + slots.lower(620));
        System.out.println("At or before 600: " + slots.floor(600));

        Integer after = slots.ceiling(901);
        System.out.println("At or after 901: " + (after == null ? "none" : after));

        List<String> pages = List.of("home", "search", "item", "search", "cart", "home", "item");
        Set<String> visited = new LinkedHashSet<>(pages);
        System.out.println("Pages: " + visited);
    }
}

