import java.util.List;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        Set<String> ana = new TreeSet<>(List.of("Math", "Art", "Physics", "History"));
        Set<String> ben = new TreeSet<>(List.of("Physics", "Music", "Math", "Chemistry"));
        List<String> required = List.of("Math", "History");

        Set<String> both = new TreeSet<>(ana);
        both.retainAll(ben);
        System.out.println("Both: " + both);

        Set<String> either = new TreeSet<>(ana);
        either.addAll(ben);
        System.out.println("Either: " + either);

        Set<String> onlyAna = new TreeSet<>(ana);
        onlyAna.removeAll(ben);
        System.out.println("Only Ana: " + onlyAna);

        System.out.println("Ana unchanged: " + ana);
        System.out.println("Ana has required: " + ana.containsAll(required));
        System.out.println("Ben has required: " + ben.containsAll(required));
    }
}

