import java.util.List;
import java.util.Set;
import java.util.TreeSet;

public class Main {
    public static void main(String[] args) {
        Set<String> mia = new TreeSet<>(List.of("Up", "Jaws", "Coco", "Heat", "Alien"));
        Set<String> leo = new TreeSet<>(List.of("Heat", "Up", "Rocky", "Alien"));
        List<String> watchlist = List.of("Coco", "Up");

        Set<String> both = new TreeSet<>(mia);
        both.retainAll(leo);
        System.out.println("Both: " + both);

        Set<String> all = new TreeSet<>(mia);
        all.addAll(leo);
        System.out.println("All: " + all);

        Set<String> onlyMia = new TreeSet<>(mia);
        onlyMia.removeAll(leo);
        System.out.println("Only Mia: " + onlyMia);

        System.out.println("Mia still: " + mia);
        System.out.println("Mia saw watchlist: " + mia.containsAll(watchlist));
    }
}
